"""
Comprehensive definitions of global fiat currencies, cryptocurrencies, and historical exchange rates.
"""

class Currency:
    def __init__(self, code, name, symbol, decimal_places, countries):
        self.code = code
        self.name = name
        self.symbol = symbol
        self.decimal_places = decimal_places
        self.countries = countries

